function spawn(generatorFn) {
  return new Promise((resolve, reject) => {
    const g = generatorFn();
    function step(nextFn) {
      let next;
      try { next = nextFn(); } catch (e) { return reject(e); }
      if (next.done) return resolve(next.value);
