手写 `useDeepCompareEffect` 的核心逻辑：
```javascript
import lodash from 'lodash';

function useDeepCompareMemoize(value) {
  const ref = useRef();
  // 只有在深层比对发现内容确实变了，才更新 ref 的物理引用
  if (!lodash.isEqual(value, ref.current)) {
    ref.current = value;
  }
  return ref.current;
}

function useDeepCompareEffect(effect, dependencies) {
  // 传入的是锁死内容的 ref 指针，从而成功让 useEffect 绕过引用地址不同的限制
  useEffect(effect, useDeepCompareMemoize(dependencies));
}
```

