双状态防抖搜索的经典实现代码：
```jsx
function SearchInput() {
  const [text, setText] = useState(''); // 紧急状态，实时控制 value，保障手感
  const [query, setQuery] = useState(''); // 非紧急状态，防抖更新，触发接口

  // 缓存防抖函数，确保每次 render 不重新创建
  const debouncedSetQuery = useCallback(
    debounce((val) => setQuery(val), 300),
    []
  );

  const handleChange = (e) => {
    const val = e.target.value;
    setText(val); // 立即更新输入框
    debouncedSetQuery(val); // 防抖触发查询
  };

  useEffect(() => {
    if (query) fetchSearchApi(query);
  }, [query]);

  return <input value={text} onChange={handleChange} />;
}
