手写一个全局防连击点击指令 `v-debounce` 的核心代码：
```javascript
app.directive('debounce', {
  mounted(el, binding) {
    let timer = null;
    el._clickDebounce = (e) => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        binding.value(e); // 执行指令绑定的回调函数
      }, binding.arg || 300); // 接收传入的毫秒时间参数
    };
    el.addEventListener('click', el._clickDebounce);
  },
  unmounted(el) {
    el.removeEventListener('click', el._clickDebounce); // 注销事件，预防内存泄漏
  }
});
```

