`customRef` 自定义防抖 Ref（useDebounceRef）经典手写：
```javascript
function useDebouncedRef(value, delay = 200) {
  return customRef((track, trigger) => {
    let timeout;
    return {
      get() {
        track(); // 收集依赖
        return value;
      },
      set(newValue) {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          value = newValue;
          trigger(); // 触发更新
        }, delay);
      }
    };
  });
}
```

