手写响应式防抖 `useDebouncedRef` 的完整 Composable 模块代码：
```javascript
import { customRef } from 'vue';

export function useDebouncedRef(value, delay = 300) {
  let timeout = null;
  return customRef((track, trigger) => {
    return {
      get() {
        track(); // 1. 显式调用 track()，让 Vue 知道该变量在哪个组件中被消费并建立依赖订阅
        return value;
      },
      set(newValue) {
        // 2. 劫持写入：清除上一个定时器，不立即通知 trigger()，实现防抖机制
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          value = newValue;
          trigger(); // 3. 延时到期后，执行 trigger()，派发更新通知渲染器重绘 DOM
        }, delay);
      }
    };
  });
}
```

