  inputEl.value.focus(); // 挂载完成，安全执行 DOM 获取和焦点调用
});

async function triggerShow() {
  showInput.value = true;
  // 错误：inputEl.value.focus(); 会直接报错！因为 v-if 的 DOM 重绘还没发生
  await nextTick();
  inputEl.value.focus(); // 正确：在下一个 DOM 周期重绘后，安全聚焦
}
</script>
<template>
